sys_script_include.script:
var GetPhoneNumber = Class.create();
GetPhoneNumber.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

	getPhone: function() {
		var userBox = new GlideRecord("sys_user"); //En esta caja vamos a meter cosas de la tabla sys_user
		userBox.get(this.getParameter('sysparm_UserId')); //Llenamos la caja, con el registro que el usuario manda desde el Client Script.
		return userBox.mobile_phone + ''; //De ese registro, queremos retornar el teléfono móvil

	},

	getCurrentPhone: function(){
		var userBox = new GlideRecord("sys_user");
		if(userBox.get(gs.getUserID())){
			return userBox.mobile_phone + '';
		}

	},

    type: 'GetPhoneNumber'
});
